package com.powercms.cms.delivery;
import com.powercms.cms.content.entity.ContentItemEntity;import com.powercms.cms.content.repo.*;import com.powercms.cms.delivery.navigation.*;import com.powercms.cms.model.repo.ContentTypeRepository;import com.powercms.cms.site.entity.SiteEntity;import com.powercms.cms.site.repo.SiteRepository;import org.junit.jupiter.api.Test;import java.time.Instant;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class RenderContextFactoryTest {@Test void exposesOnlySafeImmutableDtos(){UUID siteId=UUID.randomUUID();var sites=mock(SiteRepository.class);var site=new SiteEntity();site.setId(siteId);site.setSiteKey("demo");site.setName("Demo");site.setDefaultLocale("zh-CN");site.setTimezone("Asia/Shanghai");site.setStatus("ACTIVE");when(sites.findById(siteId)).thenReturn(Optional.of(site));var item=new ContentItemEntity();item.setId(UUID.randomUUID());item.setSiteId(siteId);item.setContentTypeId(UUID.randomUUID());item.setTitle("Page");item.setRoutePath("/docs/page");item.setStatus("PUBLISHED");var factory=new RenderContextFactory(sites,mock(CategoryRepository.class),mock(ContentItemRepository.class),mock(ContentVersionRepository.class),mock(ContentTypeRepository.class),mock(NavTreeBuilder.class),new NavBreadcrumbBuilder(),mock(UrlRewriteService.class),"test");var raw=new LinkedHashMap<String,Object>();raw.put("safe","value");raw.put("entity",item);var model=factory.create(new RenderContextFactory.Input(siteId,item,raw,false,"GET","/docs/page",Map.of("q","x"),Locale.CHINA,null,Instant.parse("2026-01-01T00:00:00Z"),Map.of()));assertNull(model.get("applicationContext"));assertNull(model.get("siteContext"));assertNull(model.get("application"));assertFalse(((Map<?,?>)model.get("contentModel")).get("entity") instanceof ContentItemEntity);assertEquals(Map.of(),model.get("cookies"));assertThrows(UnsupportedOperationException.class,()->model.put("x","y"));assertEquals("2026-01-01T00:00:00Z",model.get("now"));}}
